import { Bit } from '../common/base-server';
import { ToolRegistry } from './tool-orchestrator-service/modules/registry/tool-registry';
import { ModelRegistry } from './tool-orchestrator-service/modules/models/model-registry';
import { createDocumentStore } from '../common/persistence/factory';
import { z } from 'zod';

/**
 * ToolOrchestratorServer
 * Generated by brat bit create (Sprint 331)
 * Profile: core
 * MCP Exposure: platform-only
 * Kind: pipeline-service
 *
 * Sprint 57: Foundation - tool-orchestrator with Persistent Registries
 */
export class ToolOrchestratorServer extends Bit {
  private toolRegistry?: ToolRegistry;
  private modelRegistry?: ModelRegistry;

  constructor() {
    super({ mcpExposure: 'platform-only' });

    // Register setup to run on startup
    this.onStartup(async () => {
      await this.setup();
    });
  }

  public async setup(): Promise<void> {
    this.getLogger().info('tool_orchestrator.setup.start', {
      service: 'tool-orchestrator',
      mcpExposure: 'platform-only',
    });

    try {
      // Initialize PostgreSQL DocumentStore
      const store = await createDocumentStore();
      this.getLogger().info('tool_orchestrator.document_store_initialized');

      // Initialize ToolRegistry module
      this.toolRegistry = new ToolRegistry(store, this.getLogger() as any);
      this.getLogger().info('tool_orchestrator.tool_registry_initialized');

      // Initialize ModelRegistry module
      this.modelRegistry = new ModelRegistry(store, this.getLogger() as any);
      this.getLogger().info('tool_orchestrator.model_registry_initialized');

      // Register MCP tools
      this.registerMcpTools();
      this.getLogger().info('tool_orchestrator.mcp_tools_registered');

      // TODO: Seed model registry (Task 3.1) - run scripts/seed-model-registry.ts
      // TODO: Import tools from tool-gateway (Task 3.2) - to be done in integration testing

      this.getLogger().info('tool_orchestrator.setup.complete', {
        service: 'tool-orchestrator',
      });
    } catch (err) {
      this.getLogger().error('tool_orchestrator.setup_failed', {
        error: err instanceof Error ? err.message : String(err),
        stack: err instanceof Error ? err.stack : undefined,
      });
      throw err;
    }
  }

  public async close(reason: string = 'manual'): Promise<void> {
    this.getLogger().info('tool_orchestrator.shutdown', { reason });
    await super.close(reason);
  }

  /**
   * Register MCP tools for tool and model registry access
   */
  private registerMcpTools(): void {
    // Tool registry tools

    // tool.list - List all tools with optional filtering
    this.registerTool(
      'tool.list',
      'List all tools in the registry with optional filtering',
      z.object({
        source: z.array(z.enum(['internal', 'mcp', 'composition'])).optional(),
        status: z.array(z.enum(['active', 'deprecated', 'disabled'])).optional(),
        category: z.string().optional(),
        tags: z.array(z.string()).optional(),
      }),
      async (args) => {
        if (!this.toolRegistry) {
          throw new Error('ToolRegistry not initialized');
        }

        const tools = await this.toolRegistry.queryTools(args);

        return {
          content: [{
            type: 'text' as const,
            text: JSON.stringify({ tools, count: tools.length }, null, 2),
          }],
        };
      }
    );

    // tool.get - Get single tool metadata
    this.registerTool(
      'tool.get',
      'Get metadata for a specific tool by ID',
      z.object({
        toolId: z.string().describe('Tool ID to retrieve'),
      }),
      async (args) => {
        if (!this.toolRegistry) {
          throw new Error('ToolRegistry not initialized');
        }

        const tool = await this.toolRegistry.getTool(args.toolId);

        if (!tool) {
          throw new Error(`Tool not found: ${args.toolId}`);
        }

        return {
          content: [{
            type: 'text' as const,
            text: JSON.stringify(tool, null, 2),
          }],
        };
      }
    );

    // Model registry tools

    // model.list - List all models with optional filtering
    this.registerTool(
      'model.list',
      'List all models in the registry with optional filtering',
      z.object({
        provider: z.array(z.string()).optional(),
        tier: z.array(z.enum(['free', 'basic', 'premium', 'enterprise', 'deterministic', 'system'])).optional(),
        status: z.array(z.enum(['active', 'deprecated', 'disabled'])).optional(),
        capabilities: z.object({
          toolCalling: z.boolean().optional(),
          vision: z.boolean().optional(),
        }).optional(),
      }),
      async (args) => {
        if (!this.modelRegistry) {
          throw new Error('ModelRegistry not initialized');
        }

        const models = await this.modelRegistry.listModels(args);

        return {
          content: [{
            type: 'text' as const,
            text: JSON.stringify({ models, count: models.length }, null, 2),
          }],
        };
      }
    );

    // model.get - Get single model metadata
    this.registerTool(
      'model.get',
      'Get metadata for a specific model by ID',
      z.object({
        modelId: z.string().describe('Model ID to retrieve'),
      }),
      async (args) => {
        if (!this.modelRegistry) {
          throw new Error('ModelRegistry not initialized');
        }

        const model = await this.modelRegistry.getModel(args.modelId);

        if (!model) {
          throw new Error(`Model not found: ${args.modelId}`);
        }

        return {
          content: [{
            type: 'text' as const,
            text: JSON.stringify(model, null, 2),
          }],
        };
      }
    );

    this.getLogger().info('tool_orchestrator.mcp_tools_registration_complete', { toolsRegistered: 4 });
  }

  // Getter methods for modules (used externally if needed)
  public getToolRegistry(): ToolRegistry | undefined {
    return this.toolRegistry;
  }

  public getModelRegistry(): ModelRegistry | undefined {
    return this.modelRegistry;
  }
}

if (require.main === module) {
  const server = new ToolOrchestratorServer();
  const port = parseInt(process.env.PORT || '3000', 10);
  server.start(port).catch((err) => {
    console.error('Failed to start tool-orchestrator:', err);
    process.exit(1);
  });
}
